import React, { useMemo } from "react";

function StatCard({ label, value, sub, color }) {
  return (
    <div style={{
      background: "#12141f", borderRadius: 10, padding: "14px 16px",
      border: "1px solid #2a2d3a",
    }}>
      <div style={{ fontSize: 11, color: "#6b7280", marginBottom: 6, letterSpacing: 0.4 }}>
        {label}
      </div>
      <div style={{ fontSize: 24, fontWeight: 600, color: color || "#e8e6df" }}>
        {value}
      </div>
      {sub && <div style={{ fontSize: 11, color: "#6b7280", marginTop: 4 }}>{sub}</div>}
    </div>
  );
}

export default function StatsPanel({ alerts }) {
  const stats = useMemo(() => {
    const bottles = alerts.filter(a => a.type !== "camera_alert");
    const avgConf = bottles.length
      ? (bottles.reduce((s, a) => s + a.confidence, 0) / bottles.length * 100).toFixed(0)
      : 0;
    const last = bottles[0]
      ? new Date(bottles[0].timestamp).toLocaleTimeString()
      : "—";
    const lastMin = bottles.filter(a => {
      return Date.now() - new Date(a.timestamp).getTime() < 60000;
    }).length;
    return { total: bottles.length, avgConf, last, lastMin };
  }, [alerts]);

  return (
    <div style={{
      display: "grid", gridTemplateColumns: "repeat(4, minmax(0,1fr))",
      gap: 12, marginBottom: 16,
    }}>
      <StatCard label="TOTAL DETECTIONS" value={stats.total} color="#ef4444" />
      <StatCard label="LAST 60 SECONDS"  value={stats.lastMin} color="#f59e0b" />
      <StatCard label="AVG CONFIDENCE"   value={`${stats.avgConf}%`} />
      <StatCard label="LAST ALERT"       value={stats.last} sub="time of last event" />
    </div>
  );
}
